mongodb:
{
  "collection": "schools",
  "operation": "aggregate",
  "pipeline": [
    {
      "$match": {
        "frpm": {
          "$exists": true
        },
        "satScores": {
          "$exists": true
        },
        "satScores.excellenceRate": {
          "$gt": 0.3
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "freeMealRate": {
          "$cond": {
            "if": {
              "$and": [
                {
                  "$ne": [
                    "$frpm.enrollmentAges5to17.enrollment",
                    null
                  ]
                },
                {
                  "$gt": [
                    "$frpm.enrollmentAges5to17.enrollment",
                    0
                  ]
                }
              ]
            },
            "then": {
              "$divide": [
                {
                  "$ifNull": [
                    "$frpm.enrollmentAges5to17.freeMealCount",
                    null
                  ]
                },
                "$frpm.enrollmentAges5to17.enrollment"
              ]
            },
            "else": null
          }
        }
      }
    },
    {
      "$group": {
        "_id": null,
        "max_free_meal_rate": {
          "$max": "$freeMealRate"
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "max_free_meal_rate": 1
      }
    }
  ]
}

{
  "collection": "schools",
  "operation": "aggregate",
  "pipeline": [
    {
      "$match": {
        "frpm": {
          "$exists": true
        },
        "characteristics.charterFundingType": "Locally funded"
      }
    },
    {
      "$addFields": {
        "enrollmentDiff": {
          "$cond": {
            "if": {
              "$and": [
                {
                  "$ne": [
                    "$frpm.enrollmentK12.enrollment",
                    null
                  ]
                },
                {
                  "$ne": [
                    "$frpm.enrollmentAges5to17.enrollment",
                    null
                  ]
                }
              ]
            },
            "then": {
              "$subtract": [
                "$frpm.enrollmentK12.enrollment",
                "$frpm.enrollmentAges5to17.enrollment"
              ]
            },
            "else": null
          }
        }
      }
    },
    {
      "$group": {
        "_id": null,
        "avgDiff": {
          "$avg": "$enrollmentDiff"
        },
        "schools": {
          "$push": {
            "school": "$location.school",
            "doc": "$classification.doc",
            "enrollmentDiff": "$enrollmentDiff"
          }
        }
      }
    },
    {
      "$unwind": "$schools"
    },
    {
      "$match": {
        "$expr": {
          "$and": [
            {
              "$ne": [
                "$schools.enrollmentDiff",
                null
              ]
            },
            {
              "$gt": [
                "$schools.enrollmentDiff",
                "$avgDiff"
              ]
            }
          ]
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "School": "$schools.school",
        "DOC": "$schools.doc"
      }
    }
  ]
}

