{
  "collection": "player_attributes",
  "operation": "aggregate",
  "pipeline": [
    {
      "$lookup": {
        "from": "players",
        "localField": "playerApiId",
        "foreignField": "_id",
        "as": "player"
      }
    },
    {
      "$unwind": "$player"
    },
    {
      "$match": {
        "player.name": {
          "$in": [
            "Abdou Diallo",
            "Aaron Appindangoye"
          ]
        }
      }
    },
    {
      "$facet": {
        "abdou": [
          {
            "$match": {
              "player.name": "Abdou Diallo"
            }
          },
          {
            "$group": {
              "_id": null,
              "avg_ball_control": {
                "$avg": "$ballControl"
              }
            }
          }
        ],
        "aaron": [
          {
            "$match": {
              "player.name": "Aaron Appindangoye"
            }
          },
          {
            "$group": {
              "_id": null,
              "avg_ball_control": {
                "$avg": "$ballControl"
              }
            }
          }
        ]
      }
    },
    {
      "$project": {
        "_id": 0,
        "difference": {
          "$subtract": [
            {
              "$arrayElemAt": [
                "$abdou.avg_ball_control",
                0
              ]
            },
            {
              "$arrayElemAt": [
                "$aaron.avg_ball_control",
                0
              ]
            }
          ]
        }
      }
    }
  ]
}

{
  "collection": "races",
  "operation": "aggregate",
  "pipeline": [
    {
      "$match": {
        "name": "Australian Grand Prix",
        "circuit.lat": {
          "$exists": true,
          "$ne": null
        },
        "circuit.lng": {
          "$exists": true,
          "$ne": null
        }
      }
    },
    {
      "$group": {
        "_id": {
          "lat": "$circuit.lat",
          "lng": "$circuit.lng"
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "lat": "$_id.lat",
        "lng": "$_id.lng"
      }
    }
  ]
}

{
  "collection": "heroes",
  "operation": "aggregate",
  "pipeline": [
    {
      "$match": {
        "full_name": {
          "$in": [
            "Emil Blonsky",
            "Charles Chandler"
          ]
        }
      }
    },
    {
      "$group": {
        "_id": null,
        "emil_weight": {
          "$max": {
            "$cond": [
              {
                "$eq": [
                  "$full_name",
                  "Emil Blonsky"
                ]
              },
              "$weight_kg",
              null
            ]
          }
        },
        "charles_weight": {
          "$max": {
            "$cond": [
              {
                "$eq": [
                  "$full_name",
                  "Charles Chandler"
                ]
              },
              "$weight_kg",
              null
            ]
          }
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "CALCULATE": {
          "$subtract": [
            "$emil_weight",
            "$charles_weight"
          ]
        }
      }
    }
  ]
}
